insert into public.tastings (cocktail_id, taster_id, rating, notes, tried) values
  ((select id from public.cocktails where name = 'Three Dots and a Dash'), (select id from public.tasters where initials = 'JB'), 8.9, 'Balance - spicy/intriguing - refreshing - not too sugary', true),
  ((select id from public.cocktails where name = 'Three Dots and a Dash'), (select id from public.tasters where initials = 'GM'), 8.71, 'Balance - spicy/intriguing - refreshing - not too sugary', true),
  ((select id from public.cocktails where name = 'Painkiller'), (select id from public.tasters where initials = 'JB'), 8.59, 'Huge hit for a group. Easy to batch.', true),
  ((select id from public.cocktails where name = 'Painkiller'), (select id from public.tasters where initials = 'GM'), null, 'Don’t remember notes but was a huge hit for a group. Also easy to batch. Smooth and almost creamy but not in a thick way.', true),
  ((select id from public.cocktails where name = 'Drunken Helmsman'), (select id from public.tasters where initials = 'JB'), 8.96, 'Yum. Tastes like a tiki bar. Balance of sweet and tart. Subtle butterscotch flavor.', true),
  ((select id from public.cocktails where name = 'Drunken Helmsman'), (select id from public.tasters where initials = 'GM'), 8.96, 'Yum. Tastes like a tiki bar. Balance of sweet and tart. Subtle butterscotch flavor.', true),
  ((select id from public.cocktails where name = 'Tiki Max'), (select id from public.tasters where initials = 'JB'), null, 'Quintessential tiki flavor. Tropical and delicious.', true),
  ((select id from public.cocktails where name = 'Tiki Max'), (select id from public.tasters where initials = 'GM'), 9.41, 'The quintessential tiki flavor. Tropical and yummy and you have no idea it’s mostly booze. Yes.', true),
  ((select id from public.cocktails where name = 'Jungle Bird'), (select id from public.tasters where initials = 'JB'), 8.4, 'Bitter forward at first but liked it - grew on us at the end. Smoothed out after a few sips.', true),
